   "Лямбда компилируется в объект MethodHandle, который JVM вызывает напрямую через invokevirtual на каждом обращении.",
   "Каждый вызов лямбды заново проходит через bootstrap-метод LambdaMetafactory, поэтому класс реализации генерируется при каждом исполнении."
