  "correct": "Gadget chain исполняется внутри readObject() на этапе восстановления графа — через магические callback-методы (readObject/readResolve, а для коллекций hashCode/equals/compareTo) уже присутствующих на classpath классов, доходя по reflection до Runtime.exec()",
